THEMES = [
    'theme01_missed.md', 'theme02_knowing.md', 'theme03_polarity.md',
    'theme04_roles.md', 'theme05_hallucination.md', 'theme06_buffer.md',
    'theme07_readers.md', 'theme08_safety.md', 'theme09_judge.md',
    'theme10_surprises.md',
]

def main():
    sections=[INTRO.rstrip()]
    for name in THEMES:
        source=(HERE/name).read_text().strip()
        levels=[len(m.group(1)) for m in re.finditer(r'^(#+) ',source,re.M)]
        shift=2-min(levels)
        source=re.sub(r'^(#+) ',lambda m:'#'*(len(m.group(1))+shift)+' ',source,flags=re.M)
        sections.append(source)
    (HERE/'DISCOVERY2_2026-10-28.md').write_text('\n\n---\n\n'.join(sections)+'\n')

if __name__=='__main__':
    main()
